00085     public static function getProcessList($properties = [])
00086     {
00087         Log::debug('getProcessList: Listing processes (COM/WMI)');
00088 
00089         $startTime = microtime(true);
00090 
00091         try {
00092             // Create WMI connection
00093             $wmi = self::getWmiCimv2();
00094 
00095             // Build WQL query
00096             if (empty($properties)) {
00097                 $properties = ['Name', 'ProcessID', 'ExecutablePath'];
00098             }
00099 
00100             $selectClause = implode(', ', $properties);
00101             $query = "SELECT {$selectClause} FROM Win32_Process";
00102 
00103             // Execute query
00104             $processes = $wmi->ExecQuery($query);
00105 
00106             // Convert to array
00107             $result = [];
00108             foreach ($processes as $proc) {
00109                 $process = [];
00110                 foreach ($properties as $prop) {
00111                     // Handle property access
00112                     try {
00113                         $value = $proc->$prop;
00114                         $process[$prop] = $value ?? '';
00115                     } catch (Exception $e) {
00116                         $process[$prop] = '';
00117                     }
00118                 }
00119                 $result[] = $process;
00120             }
00121 
00122             $duration = round((microtime(true) - $startTime) * 1000, 2);
00123             Log::debug('getProcessList: Found ' . count($result) . ' processes in ' . $duration . 'ms (COM/WMI)');
00124 
00125             return $result;
00126 
00127         } catch (Exception $e) {
00128             self::resetConnections();
00129             Log::error('getProcessList: COM exception: ' . $e->getMessage());
00130             return [];
00131         }
00132     }
