00141     public static function killProcess($pid)
00142     {
00143         // Validate PID
00144         if (!is_numeric($pid) || $pid <= 0) {
00145             Log::error('killProcess: Invalid PID: ' . $pid);
00146             return false;
00147         }
00148 
00149         Log::debug('killProcess: Killing process PID ' . $pid . ' (COM/WMI)');
00150 
00151         $startTime = microtime(true);
00152 
00153         try {
00154             // Create WMI connection
00155             $wmi = self::getWmiCimv2();
00156 
00157             // Query for specific process
00158             $query = "SELECT * FROM Win32_Process WHERE ProcessID = {$pid}";
00159             $processes = $wmi->ExecQuery($query);
00160 
00161             // Terminate the process
00162             $found = false;
00163             $terminateResult = null;
00164             foreach ($processes as $proc) {
00165                 $terminateResult = $proc->Terminate();
00166                 $found = true;
00167                 break;
00168             }
00169 
00170             $duration = round((microtime(true) - $startTime) * 1000, 2);
00171 
00172             if (!$found) {
00173                 Log::debug('killProcess: Process ' . $pid . ' not found');
00174                 return false;
00175             }
00176 
00177             // Check if Terminate() returned success (0 = success)
00178             if ($terminateResult !== 0) {
00179                 Log::error('killProcess: Terminate() failed with status code: ' . $terminateResult);
00180                 return false;
00181             }
00182 
00183             // Additional verification: check if process still exists after a short delay
00184             usleep(100000); // Wait 100ms for termination to take effect
00185             if (self::processExists($pid)) {
00186                 Log::error('killProcess: Process ' . $pid . ' still exists after termination attempt');
00187                 return false;
00188             }
00189 
00190             Log::debug('killProcess: Successfully killed process ' . $pid . ' in ' . $duration . 'ms (COM/WMI)');
00191             return true;
00192 
00193         } catch (Exception $e) {
00194             self::resetConnections();
00195             Log::error('killProcess: COM exception: ' . $e->getMessage());
00196             return false;
00197         }
00198     }
