00295             // Sanitize the name parameter to prevent WQL injection
00296             // Escape single quotes by doubling them (WQL standard)
00297             $safeName = str_replace("'", "''", $name);
00298 
00299             $query = "SELECT {$selectClause} FROM Win32_Process WHERE Name = '{$safeName}'";
00300             $processes = $wmi->ExecQuery($query);
