00345     private static function mapRegistryHive($hive)
00346     {
00347         $hiveMap = [
00348             'HKLM' => 'HKLM',
00349             'HKCU' => 'HKCU',
00350             'HKCR' => 'HKCR',
00351             'HKU' => 'HKU',
00352             'HKEY_LOCAL_MACHINE' => 'HKLM',
00353             'HKEY_CURRENT_USER' => 'HKCU',
00354             'HKEY_CLASSES_ROOT' => 'HKCR',
00355             'HKEY_USERS' => 'HKU',
00356         ];
00357 
00358         return isset($hiveMap[$hive]) ? $hiveMap[$hive] : $hive;
00359     }
