00373     public static function registryExists($hive, $key, $value = null)
00374     {
00375         $hive = self::mapRegistryHive($hive);
00376         $regPath = $hive . '\\' . $key;
00377 
00378         Log::debug('registryExists: Checking ' . $regPath . ($value !== null ? '\\' . $value : ' (key)') . ' (COM)');
00379 
00380         try {
00381             if ($value === null) {
00382                 // Check if the key itself exists
00383                 // Use StdRegProv::EnumKey for reliable key existence checking
00384                 // This avoids false negatives from checking for a default value that may not exist
00385                 try {
00386                     $wmi = self::getWmiStdRegProv();
00387 
00388                     // Map hive names to WMI constants
00389                     $hiveConstMap = [
00390                         'HKCR' => 0x80000000,  // HKEY_CLASSES_ROOT
00391                         'HKCU' => 0x80000001,  // HKEY_CURRENT_USER
00392                         'HKLM' => 0x80000002,  // HKEY_LOCAL_MACHINE
00393                         'HKU'  => 0x80000003,  // HKEY_USERS
00394                     ];
00395                     
00396                     $hConst = $hiveConstMap[$hive] ?? 0x80000002;  // Default to HKLM
00397 
00398                     // EnumKey checks if parent key's subkeys contain the requested key
00399                     // For root-level checks, pass empty parent
00400                     $pathParts = explode('\\', $key);
00401                     
00402                     if (count($pathParts) === 1) {
00403                         // Top-level key: parent is root
00404                         $parentKey = '';
00405                         $keyName = $pathParts[0];
00406                     } else {
00407                         // Nested key: split parent from key name
00408                         $keyName = array_pop($pathParts);
00409                         $parentKey = implode('\\', $pathParts);
00410                     }
00411                     
00412                     $subKeys = null;
00413                     $rc = $wmi->EnumKey($hConst, $parentKey, $subKeys);
00414                     
00415                     if ($rc !== 0 || !is_array($subKeys)) {
00416                         Log::debug('registryExists: Key not found (EnumKey failed)');
00417                         return false;
00418                     }
00419                     
00420                     // Check if our key name is in the list of subkeys
00421                     $exists = false;
00422                     foreach ($subKeys as $subKey) {
00423                         if (strcasecmp($subKey, $keyName) === 0) {
00424                             $exists = true;
00425                             break;
00426                         }
00427                     }
00428                     
00429                     if ($exists) {
00430                         Log::debug('registryExists: Key found');
00431                         return true;
00432                     } else {
00433                         Log::debug('registryExists: Key not found');
00434                         return false;
00435                     }
00436 
00437                 } catch (Exception $e) {
00438                     self::$wmiStdRegProv = null;
00439                     Log::error('registryExists: StdRegProv exception during key check: ' . $e->getMessage());
00440                     return false;
00441                 }
00442             } else {
00443                 // Check if a specific value exists within the key
00444                 // Use WScript.Shell::RegRead for value existence
00445                 try {
00446                     $shell = self::getWscriptShell();
00447                     $valuePath = $regPath . '\\' . $value;
00448                     $shell->RegRead($valuePath);
00449                     Log::debug('registryExists: Value found');
00450                     return true;
00451                 } catch (Exception $e) {
00452                     Log::debug('registryExists: Value not found');
00453                     return false;
00454                 }
00455             }
00456 
00457         } catch (Exception $e) {
00458             self::resetConnections();
00459             Log::error('registryExists: COM exception: ' . $e->getMessage());
00460             return false;
00461         }
00462     }
