00473     public static function registryGetValue($hive, $key, $value = '')
00474     {
00475         $hive = self::mapRegistryHive($hive);
00476         $regPath = $hive . '\\' . $key;
00477 
00478         if ($value !== '') {
00479             $regPath .= '\\' . $value;
00480         } else {
00481             // For default value, append backslash
00482             $regPath .= '\\';
00483         }
00484 
00485         Log::debug('registryGetValue: Reading ' . $regPath . ' (COM)');
00486 
00487         $startTime = microtime(true);
