00489         try {
00490             $shell = self::getWscriptShell();
00491             $result = $shell->RegRead($regPath);
00492 
00493             $duration = round((microtime(true) - $startTime) * 1000, 2);
00494 
00495             // Convert result to appropriate PHP type
00496             if (is_object($result)) {
00497                 // COM objects need special handling
00498                 $result = (string)$result;
00499             }
00500 
00501             Log::debug('registryGetValue: Found value in ' . $duration . 'ms (COM)');
00502             return $result;
