00749     public static function countFilesFolders($path)
00750     {
00751         Log::debug('countFilesFolders: Counting in ' . $path . ' (Native PHP)');
00752 
00753         $startTime = microtime(true);
00754 
00755         try {
00756             if (!is_dir($path)) {
00757                 Log::error('countFilesFolders: Path is not a directory: ' . $path);
00758                 return false;
00759             }
00760 
00761             $count = 0;
00762 
00763             // Use RecursiveDirectoryIterator for efficient recursive counting
00764             try {
00765                 $iterator = new RecursiveIteratorIterator(
00766                     new RecursiveDirectoryIterator($path, RecursiveDirectoryIterator::SKIP_DOTS),
00767                     RecursiveIteratorIterator::SELF_FIRST
00768                 );
00769 
00770                 foreach ($iterator as $item) {
00771                     $count++;
00772                 }
00773             } catch (Exception $e) {
00774                 // If RecursiveIterator fails, fall back to manual recursion
00775                 Log::debug('countFilesFolders: RecursiveIterator failed, using manual recursion');
00776                 $count = self::countFilesFoldersManual($path);
00777             }
00778 
00779             $duration = round((microtime(true) - $startTime) * 1000, 2);
00780             Log::debug('countFilesFolders: Counted ' . $count . ' items in ' . $duration . 'ms (Native PHP)');
00781 
00782             return $count;
00783 
00784         } catch (Exception $e) {
00785             Log::error('countFilesFolders: Exception: ' . $e->getMessage());
00786             return false;
00787         }
00788     }
