00797     private static function countFilesFoldersManual($path)
00798     {
00799         $count = 0;
00800 
00801         try {
00802             $items = @scandir($path);
00803 
00804             if ($items === false) {
00805                 return 0;
00806             }
00807 
00808             foreach ($items as $item) {
00809                 if ($item === '.' || $item === '..') {
00810                     continue;
00811                 }
00812 
00813                 $fullPath = $path . DIRECTORY_SEPARATOR . $item;
00814                 $count++; // Count this item
00815 
00816                 if (is_dir($fullPath)) {
00817                     // Recursively count subdirectory
00818                     $count += self::countFilesFoldersManual($fullPath);
00819                 }
00820             }
00821         } catch (Exception $e) {
00822             // Silently handle errors (permission denied, etc.)
00823         }
00824 
00825         return $count;
00826     }
