00856         } catch (Exception $e) {
00857             Log::error('countFilesFoldersCOM: COM exception: ' . $e->getMessage());
00858             return false;
00859         }
00860     }
00861 
00870     private static function countFolderItemsCOM($fso, $path)
00871     {
00872         try {
00873             $folder = $fso->GetFolder($path);
00874 
00875             // Count files and subfolders in this folder
00876             $count = $folder->Files->Count + $folder->SubFolders->Count;
00877 
00878             // Recursively count subfolders
00879             foreach ($folder->SubFolders as $subFolder) {
00880                 $count += self::countFolderItemsCOM($fso, $subFolder->Path);
00881             }
00882 
00883             return $count;
00884 
00885         } catch (Exception $e) {
00886             // Silently handle errors (permission denied, etc.)
00887             return 0;
00888         }
00889     }
