00903     public static function getServiceInfo($serviceName, $properties = [])
00904     {
00905         Log::debug('getServiceInfo: Getting info for service ' . $serviceName . ' (COM/WMI)');
00906 
00907         $startTime = microtime(true);
00908 
00909         try {
00910             // Create WMI connection
00911             $wmi = self::getWmiCimv2();
00912 
00913             // Default properties if none specified
00914             if (empty($properties)) {
00915                 $properties = [
00916                     'Name',
00917                     'DisplayName',
00918                     'State',
00919                     'Status',
00920                     'StartMode',
00921                     'PathName',
00922                     'ProcessId',
00923                     'Started',
00924                     'StartName',
00925                     'Description'
00926                 ];
00927             }
00928 
00929             // Build WQL query
00930             $selectClause = implode(', ', $properties);
00931             $safeServiceName = str_replace("'", "''", $serviceName);
00932             $query = "SELECT {$selectClause} FROM Win32_Service WHERE Name = '{$safeServiceName}'";
00933 
00934             // Execute query
00935             $services = $wmi->ExecQuery($query);
00936 
00937             // Get the first (and should be only) result
00938             foreach ($services as $service) {
00939                 $result = [];
00940                 foreach ($properties as $prop) {
00941                     try {
00942                         $value = $service->$prop;
00943                         $result[$prop] = $value ?? '';
00944                     } catch (Exception $e) {
00945                         $result[$prop] = '';
00946                     }
00947                 }
00948 
00949                 $duration = round((microtime(true) - $startTime) * 1000, 2);
00950                 Log::debug('getServiceInfo: Found service in ' . $duration . 'ms (COM/WMI)');
00951 
00952                 return $result;
00953             }
00954 
00955             // Service not found
00956             Log::debug('getServiceInfo: Service not found');
00957             return false;
00958 
00959         } catch (Exception $e) {
00960             self::resetConnections();
00961             Log::error('getServiceInfo: COM exception: ' . $e->getMessage());
00962             return false;
00963         }
00964     }
