01036             $query = "SELECT Name FROM Win32_Service WHERE Name = '{$safeServiceName}'";
01037 
01038             // Execute query
01039             $services = $wmi->ExecQuery($query);
01040 
01041             foreach ($services as $service) {
01042                 return true;
