01094     public static function getDefaultBrowser()
01095     {
01096         Log::debug('getDefaultBrowser: Reading default browser (COM)');
01097 
01098         $startTime = microtime(true);
01099 
01100         // Try to read the default browser from registry
01101         $browserPath = self::registryGetValue('HKLM', 'SOFTWARE\\Classes\\http\\shell\\open\\command', '');
01102 
01103         if ($browserPath === null) {
01104             Log::debug('getDefaultBrowser: No default browser found');
01105             return false;
01106         }
01107 
01108         $duration = round((microtime(true) - $startTime) * 1000, 2);
01109 
01110         // Extract the executable path from the command
01111         // Format is usually: "C:\Program Files\Browser\browser.exe" -- "%1"
01112         if (preg_match('/"([^"]+)"/', $browserPath, $matches)) {
01113             $path = $matches[1];
01114         } else {
01115             // No quotes, take everything before the first space or use as-is
01116             $path = trim(explode(' ', $browserPath)[0]);
01117             $path = str_replace('"', '', $path);
01118         }
01119 
01120         Log::debug('getDefaultBrowser: Found browser in ' . $duration . 'ms (COM)');
01121         return $path;
01122     }
01123 
01130     public static function getInstalledBrowsers()
01131     {
01132         Log::debug('getInstalledBrowsers: Enumerating installed browsers (Hybrid - No VBS)');
01133 
01134         $startTime = microtime(true);
01135         $browsers = [];
01136 
01137         // Known browser registry names (covers 99% of browsers)
01138         $knownBrowsers = [
01139             // Major browsers
01140             'Google Chrome',
01141             'Microsoft Edge',
01142             'Opera',
01143             'Brave',
01144             'Vivaldi',
01145             'Chromium',
01146 
01147             // Firefox variants
01148             'Firefox',
01149             'Firefox-308046B0AF4A39CB',  // Common Firefox GUID
01150             'Firefox Developer Edition',
01151             'Firefox Nightly',
01152 
01153             // Other browsers
01154             'Safari',
01155             'Waterfox',
01156             'Pale Moon',
01157             'Yandex',
01158             'IEXPLORE.EXE',
01159             'Total Browser',
01160             'Maxthon',
01161             'Seamonkey',
01162             'K-Meleon',
01163             'Basilisk',
01164             'Tor Browser',
01165             'Slimjet',
01166             'Epic Privacy Browser',
01167             'Comodo Dragon',
01168             'SRWare Iron',
01169             'Cent Browser',
01170             '360 Browser',
01171             'UC Browser',
01172             'Avast Secure Browser',
01173             'AVG Secure Browser',
01174         ];
01175 
01176         // Registry paths to check
01177         $registryPaths = [
01178             ['hive' => 'HKLM', 'key' => 'SOFTWARE\\WOW6432Node\\Clients\\StartMenuInternet'],
01179             ['hive' => 'HKLM', 'key' => 'SOFTWARE\\Clients\\StartMenuInternet'],
01180             ['hive' => 'HKCU', 'key' => 'SOFTWARE\\Clients\\StartMenuInternet'],
01181         ];
01182 
01183         // Check each known browser in each registry path
01184         foreach ($registryPaths as $regPath) {
01185             $hive = $regPath['hive'];
01186             $basePath = $regPath['key'];
01187 
01188             foreach ($knownBrowsers as $browserName) {
01189                 try {
01190                     // Try to read the browser's command path
01191                     $commandPath = self::registryGetValue(
01192                         $hive,
01193                         $basePath . '\\' . $browserName . '\\shell\\open\\command',
01194                         ''
01195                     );
01196 
01197                     if ($commandPath !== null && !empty($commandPath)) {
01198                         // Extract executable path
01199                         $exePath = self::extractBrowserExecutablePath($commandPath);
01200 
01201                         if ($exePath && !in_array($exePath, $browsers)) {
01202                             Log::debug('getInstalledBrowsers: Found ' . $browserName . ': ' . $exePath);
01203                             $browsers[] = $exePath;
01204                         }
01205                     }
01206                 } catch (Exception $e) {
01207                     // Browser not found, continue
01208                     continue;
01209                 }
01210             }
01211         }
01212 
01213         $duration = round((microtime(true) - $startTime) * 1000, 2);
01214         Log::debug('getInstalledBrowsers: Found ' . count($browsers) . ' browser(s) in ' . $duration . 'ms (Hybrid - No VBS)');
01215 
01216         // Always return an array (possibly empty) to simplify call sites
01217         return $browsers;
01218     }
01219 
01227     private static function extractBrowserExecutablePath($commandPath)
01228     {
01229         if (empty($commandPath)) {
01230             return false;
01231         }
01232 
01233         // Method 1: Extract path from quotes
01234         // Format: "C:\Program Files\Browser\browser.exe" --arguments
01235         if (preg_match('/"([^"]+\\.exe)"/i', $commandPath, $matches)) {
01236             return $matches[1];
01237         }
01238 
01239         // Method 2: Extract path without quotes but with .exe
01240         // Format: C:\Program Files\Browser\browser.exe --arguments
01241         if (preg_match('/^([^\\s]+\\.exe)/i', trim($commandPath), $matches)) {
01242             return $matches[1];
01243         }
01244 
01245         // Method 3: Handle paths with spaces but no quotes (rare)
01246         // Try to find .exe in the string
01247         if (preg_match('/([A-Z]:\\\\[^"]+\\.exe)/i', $commandPath, $matches)) {
01248             return $matches[1];
01249         }
01250 
01251         // Method 4: Fallback - take everything before first space
01252         $parts = explode(' ', trim($commandPath));
01253         $path = str_replace('"', '', $parts[0]);
01254 
01255         // Validate it looks like a path
01256         if (stripos($path, '.exe') !== false) {
01257             return $path;
01258         }
01259 
01260         return false;
01261     }
01262 }
